package plugin

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// TestFixtures are hand-assembled wasm modules generated by the emitter kept
// alongside them (see testdata/README.md). These tests pin the host ABI so a
// plugin author gets a clear error instead of a hang.

func fixture(t *testing.T, name string) []byte {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("testdata", name+".wasm"))
	if err != nil {
		t.Fatalf("read fixture %s: %v", name, err)
	}
	return data
}

func runFixture(t *testing.T, name string, limits Limits) (Result, error) {
	t.Helper()
	if limits.Timeout == 0 {
		limits.Timeout = 2e9
	}
	if limits.MaxInput == 0 {
		limits.MaxInput = 4096
	}
	if limits.MaxOutput == 0 {
		limits.MaxOutput = 4096
	}
	p := wasmPlugin{
		manifest: Manifest{Name: name, Limits: limits},
		wasm:     fixture(t, name),
	}
	return run(context.Background(), p, []byte(`{}`))
}

func TestRunReportsMissingAlloc(t *testing.T) {
	_, err := runFixture(t, "alloc", Limits{})
	if err == nil || !strings.Contains(err.Error(), "missing exported process function") {
		t.Fatalf("expected missing process error, got %v", err)
	}
}

func TestRunReportsMissingProcess(t *testing.T) {
	_, err := runFixture(t, "noproc", Limits{})
	if err == nil || !strings.Contains(err.Error(), "missing exported process function") {
		t.Fatalf("expected missing process error, got %v", err)
	}
}

func TestRunRejectsOversizedOutput(t *testing.T) {
	if _, err := runFixture(t, "echo", Limits{MaxOutput: 4}); err == nil {
		t.Fatal("expected output size error")
	}
}

func TestRunRejectsNoOutput(t *testing.T) {
	// alloc.wasm's process returns 0, which means "no packed result".
	_, err := runFixture(t, "alloc", Limits{})
	if err == nil || !strings.Contains(err.Error(), "missing exported process") {
		t.Fatalf("expected missing process error, got %v", err)
	}
}

func TestRunInterruptsRunawayGuest(t *testing.T) {
	if _, err := runFixture(t, "spin", Limits{Timeout: 50_000_000}); err == nil {
		t.Fatal("expected timeout error")
	}
}
